struct Excerpt<'a> { part: &'a str }
impl<'a> Excerpt<'a> {
    fn part(&self) -> &str { self.part }
}

let text = String::from("abc def");
let p;
{
    let e = Excerpt { part: &text[..3] };
    p = e.part();
}
println!("{p}");
